export type ShareholderOnePercentRow = (typeof shareholderOnePercentRows)[number];
export type ShareholderFivePercentRow = (typeof shareholderFivePercentRows)[number];

export function getShareholderOnePercentRows(ticker: string) {
  return shareholderOnePercentRows.filter((row) => row.ticker === ticker.toUpperCase());
}

export function getShareholderFivePercentRows(ticker: string) {
  return shareholderFivePercentRows.filter((row) => row.ticker === ticker.toUpperCase());
}
